export const BASIC_COURSE_ID = 'basic-965-v2';
export const BASIC_COURSE_TITLE = '978 từ cơ bản';
export const BASIC_COURSE_SOURCE_COMMIT = '388adc0826300912e5b0311c089e0e70494b065f';
export const BASIC_COURSE_ATTRIBUTION = 'Nguồn: Skypedia / MinhQND, CC BY-SA 4.0. https://github.com/skypediacode/english-vietnamese-dictionary/tree/388adc0826300912e5b0311c089e0e70494b065f';

export const BASIC_COURSE_LESSONS: BasicCourseLesson[] = lessonSpecs.map(lesson => ({
  ...lesson,
  words: courseRows.filter(row => row[0] === lesson.id).map(([, id, dictionaryEntryId, dictionarySenseId, term, definition, pos, subPos, ipa]) => ({
    id, dictionaryEntryId, dictionarySenseId, term, definition, pos, subPos, ipa,
  })),
}));

export const BASIC_COURSE_WORD_COUNT = BASIC_COURSE_LESSONS.reduce((sum, lesson) => sum + lesson.words.length, 0);

export function displayCourseMeaning(word: BasicCourseWord): string {
  const kind = [word.pos, word.subPos].filter(Boolean).join(' · ');
  return `${kind ? `(${kind}) ` : ''}${word.definition}`;
}
